 ('service_tx', 'Write a Spring Boot 4 service TransferService with a @Transactional method transfer(fromId, toId, amount) that moves money between two Account entities and throws IllegalArgumentException when the balance is too low; include the entity, repository and a @DataJpaTest-style test.',
  {'Account.java': 'package {pkg};\n\nimport jakarta.persistence.Entity;\nimport jakarta.persistence.GeneratedValue;\nimport jakarta.persistence.Id;\nimport java.math.BigDecimal;\n\n@Entity\npublic class Account {\n\n    @Id\n    @GeneratedValue\n    private Long id;\n\n    private BigDecimal balance;\n\n    protected Account() {\n    }\n\n    public Account(BigDecimal balance) {\n        this.balance = balance;\n    }\n\n    public Long getId() {\n        return id;\n    }\n\n    public BigDecimal getBalance() {\n        return balance;\n    }\n\n    public void setBalance(BigDecimal balance) {\n        this.balance = balance;\n    }\n}\n',
   'AccountRepository.java': 'package {pkg};\n\nimport org.springframework.data.jpa.repository.JpaRepository;\n\npublic interface AccountRepository extends JpaRepository<Account, Long> {\n}\n',
   'TransferService.java': 'package {pkg};\n\nimport java.math.BigDecimal;\nimport org.springframework.stereotype.Service;\nimport org.springframework.transaction.annotation.Transactional;\n\n@Service\npublic class TransferService {\n\n    private final AccountRepository accounts;\n\n    public TransferService(AccountRepository accounts) {\n        this.accounts = accounts;\n    }\n\n    @Transactional\n    public void transfer(long fromId, long toId, BigDecimal amount) {\n        Account from = accounts.findById(fromId).orElseThrow();\n        Account to = accounts.findById(toId).orElseThrow();\n        if (from.getBalance().compareTo(amount) < 0) {\n            throw new IllegalArgumentException("Insufficient balance");\n        }\n        from.setBalance(from.getBalance().subtract(amount));\n        to.setBalance(to.getBalance().add(amount));\n    }\n}\n'},
  {'TransferServiceTest.java': 'package {pkg};\n\nimport static org.assertj.core.api.Assertions.assertThat;\nimport static org.assertj.core.api.Assertions.assertThatThrownBy;\n\nimport java.math.BigDecimal;\nimport org.junit.jupiter.api.Test;\nimport org.springframework.beans.factory.annotation.Autowired;\nimport org.springframework.boot.data.jpa.test.autoconfigure.DataJpaTest;\nimport org.springframework.context.annotation.Import;\n\n@DataJpaTest\n@Import(TransferService.class)\nclass TransferServiceTest {\n\n    @Autowired\n    AccountRepository accounts;\n\n    @Autowired\n    TransferService service;\n\n    @Test\n    void movesMoney() {\n        Account a = accounts.save(new Account(new BigDecimal("100")));\n        Account b = accounts.save(new Account(new BigDecimal("5")));\n        service.transfer(a.getId(), b.getId(), new BigDecimal("40"));\n        assertThat(accounts.findById(a.getId()).orElseThrow().getBalance()).isEqualByComparingTo("60");\n        assertThat(accounts.findById(b.getId()).orElseThrow().getBalance()).isEqualByComparingTo("45");\n    }\n\n    @Test\n    void refusesOverdraft() {\n        Account a = accounts.save(new Account(new BigDecimal("10")));\n        Account b = accounts.save(new Account(new BigDecimal("0")));\n        assertThatThrownBy(() -> service.transfer(a.getId(), b.getId(), new BigDecimal("50"))).isInstanceOf(IllegalArgumentException.class);\n    }\n}\n'}),
