def answer(tid, files, tests, with_tests):
    pkg = f'{P}.{tid}'
    main_first = sorted(files.items(), key=lambda kv: (kv[1].lstrip().startswith('package') and ('public record' in kv[1] or 'extends RuntimeException' in kv[1])), )  # the class you asked for first; small records and exceptions after, so the answer never runs out before the main class
    parts = [f'`{name}`:\n\n```java\n{code.replace("{pkg}", pkg)}```' for name, code in main_first]
    if with_tests: parts += [f'Test `{name}`:\n\n```java\n{code.replace("{pkg}", pkg)}```' for name, code in tests.items()]
    return '\n\n'.join(parts)


ASK = ['{t}', 'Spring Boot 4.1: {t}', '{t} Use Spring Boot 4 APIs (Jakarta, the new test modules, @MockitoBean).', '{t} Include the test.']


def springboot_task(r, verified=None):
    """One verified Spring Boot task: the request (a few phrasings) -> the code (and its test when asked)."""
    pool = [t for t in TASKS if verified is None or t[0] in verified]
    tid, req, files, tests = r.choice(pool); ask = r.choice(ASK); with_tests = 'test' in ask.lower() or 'test' in req.lower()
    return ask.format(t=req), answer(tid, files, tests, with_tests)


